fn determine_winner(a: i8, b: i8, c: i8, d: i8) -> String {
    // Helper to compute the final score for a participant
    fn score(p: i32, t: i32) -> i32 {
        let option1 = 3 * p / 10;
        let option2 = p - p * t / 250;
        std::cmp::max(option1, option2)
    }

    // Cast inputs to a wider integer type to avoid overflow
    let p1 = a as i32;
    let t1 = b as i32;
    let p2 = c as i32;
    let t2 = d as i32;

    let s1 = score(p1, t1);
    let s2 = score(p2, t2);

    if s1 > s2 {
        "Misha".to_string()
    } else if s2 > s1 {
        "Vasya".to_string()
    } else {
        "Tie".to_string()
    }
}

